#include "frontend.hpp"
#include <iostream>
#include <fstream>
#include <stdexcept>
using namespace ofo;
static void require(bool x,const char*s){if(!x)throw std::runtime_error(s);}
int main(int argc,char**argv){try{auto empty=fs::temp_directory_path()/"openfo054_empty_career_resources";fs::create_directories(empty);Resources r(argc>1?argv[1]:empty.string());CareerRules rules(r);
 // Synthetic graph exercises every transition without relying on asset availability.
 CareerRules synthetic(r);synthetic.events={{1,1,1,1,{1000,500,300}},{2,1,1,2,{1000,500,300}},{3,1,1,3,{1000,500,300}},{4,2,1,1,{2000,1000,500}},{5,2,1,2,{2000,1000,500}},{6,2,1,3,{2000,1000,500}},{7,3,1,1,{3000,1500,700}},{8,3,1,2,{3000,1500,700}},{9,3,1,3,{3000,1500,700}}};
 CareerProgress p;p.initialize();require(p.unlocked(synthetic,1)&&!p.unlocked(synthetic,2),"first stage unlock");auto finish=[&](int level,int place,bool finished=true,bool dnf=false){p.pending=true;p.pending_level=level;return p.settle(synthetic,place,100,finished,dnf);};require(finish(1,4)==0&&!p.unlocked(synthetic,2),"fourth does not qualify");require(finish(1,3)==300&&p.unlocked(synthetic,2),"bronze qualifies");require(p.settle(synthetic,1,100,true)==0,"same result idempotent");require(finish(2,1)==1000,"normal purse");require(finish(3,1)==5000&&p.highest_class==2,"class one prize and unlock");require(finish(3,1)==1000,"class prize once, regular repeat purse");require(finish(4,1,false,true)==0&&!p.position(4),"DNF earns nothing");finish(4,1);finish(5,1);require(finish(6,1)==10000&&p.highest_class==3,"class two unlock");finish(7,1);finish(8,1);require(finish(9,1)==28000&&p.classes_paid[2],"career completion");CareerProgress loaded;loaded.load(p.json());require(loaded.highest_class==3&&loaded.position(9)==1&&!loaded.pending,"progress persistence, no stale award");
 if(argc>1){require(rules.events.size()==48,"original mapping 36 road plus 12 bonus events");CareerProgress original;original.initialize();require(original.unlocked(rules,7)&&original.unlocked(rules,1)&&original.unlocked(rules,5),"original class C starters");require(!original.unlocked(rules,2)&&!original.unlocked(rules,39),"original stage and class locks");require(original.unlocked(rules,19)&&original.unlocked(rules,20)&&original.unlocked(rules,22)&&original.unlocked(rules,25),"original starter bonuses");require(rules.event(7)&&rules.event(7)->prizes[0]==1000,"original payout parsed");CareerProgress full;full.initialize();int road_count=0;for(int c=1;c<=3;++c){for(int stage=1;stage<=3;++stage)for(const auto&e:rules.events)if(e.car_class==c&&e.stage==stage){require(full.unlocked(rules,e.level),"native campaign stage unlocked in sequence");full.pending=true;full.pending_level=e.level;int paid=full.settle(rules,1,120,true);require(paid>=e.prizes[0],"native event pays actual first prize");++road_count;}require(full.classes_paid[c-1],"native all course finals complete class");}require(road_count==36&&full.classes_paid[2],"all 36 original road events complete campaign");auto temp=fs::temp_directory_path()/"openfo054_career_test";fs::remove_all(temp);Frontend f(r,temp);f.enter_career();require(f.money==4000&&f.page==MenuPage::CarSelect,"new career money and starter dealer");size_t affordable=f.cars.size();for(size_t i=0;i<f.cars.size();++i)if(f.cars[i].car_class==1&&f.cars[i].stats.price>0&&f.cars[i].stats.price<=4000){affordable=i;break;}require(affordable<f.cars.size(),"original affordable starter");f.select_car(affordable);int price=f.cars[affordable].stats.price;require(f.buy_career_car()&&f.money==4000-price,"starter purchase");for(size_t i=0;i<f.track_slots.size();++i)if(f.track_slots[i].level==7)f.select_track(i);require(f.choice.laps==3&&f.choice.bots==7&&!f.choice.stage.empty()&&f.choice.ai_handicap_level>0,"native event parameters");require(f.begin_career_race(),"career launch");int before=f.money;f.complete_career_race(Json::array({{{"car",0},{"rank",3},{"time",123.},{"finished",true}}}));require(f.money==before+rules.event(7)->prizes[2]&&f.career_event_unlocked(2),"native result payout and unlock");int after=f.money;f.complete_career_race(Json::array({{{"car",0},{"rank",3},{"time",123.},{"finished",true}}}));require(f.money==after,"duplicate frame no award");f.begin_career_race();f.cancel_career_race();f.complete_career_race(Json{{"rank",1},{"time",1.},{"finished",true}});require(f.money==after,"retire no award");Frontend restored(r,temp);restored.enter_career();require(restored.money==after&&restored.career_progress.car==f.career_progress.car&&restored.career_event_unlocked(2),"durable career restore");restored.page=MenuPage::RaceSetup;restored.selected_class=1;require(!restored.draw_commands(1280,720).empty(),"career grid draw");fs::remove_all(temp);}
 std::cout<<"career: progression, seven-place payout, class prizes, idempotence, DNF, starter purchase and persistence passed\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
